/**
 * Owns the production finite-board rejection dispatch used before game assembly.
 * Input is a normalized ReadonlyBoardConfig; output is the original first violation or
 * null in exactly the existing order. No roles, state or effects are created.
 * DemonHunter uses the owned Node snapshot ingress before its inert support
 * predicate, preserving the existing rejection boundary. A verdict alone grants
 * no runtime capability.
 * Archive verification does not import this production dispatch or its policies.
 */
import {
  isAnimalDreamPreset,
  isFragrantPairSeerPreset,
  isNobleSecretBodyPreset,
  isTricksterPreset,
  isOrderPrincePreset,
  isScholarMentorPreset,
  isMistRavenPreset,
  isRadiantEclipsePreset,
  isTimeConsortPreset,
  isWolfSorcererPreset,
  isMagicianPreset,
  isRedMoonPreset,
  isNightmarePreset,
  isEvilKnightPreset,
  isPureWhitePreset,
  isGhostBridePreset,
} from "./support";
import { Role, WinCondition } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { isDemonHunterPreset } from "./node-board-support";

/** Shared finite-board eligibility for configuration checks and direct bootstrap callers. */
export function boardPresetViolation(config: ReadonlyBoardConfig) {
  if (
    (config.animalDream ||
      config.bear?.signalPolicy === "netease_dawn_live_v1" ||
      config.whiteCat ||
      config.pufferfish ||
      config.roleSetups.some(
        (row) => [Role.WhiteCat, Role.FoxCub, Role.Pufferfish].includes(row.role) && row.count > 0,
      )) &&
    !isAnimalDreamPreset(config)
  )
    return "animal_dream_preset_invalid";
  if (config.bear && !config.roleSetups.some((row) => row.role === Role.Bear && row.count > 0))
    return "bear_role_required";
  if (
    (config.fragrantPairSeer ||
      config.roleSetups.some(
        (row) =>
          (row.role === Role.FragrantPhantom || row.role === Role.AwakenedSeer) && row.count > 0,
      )) &&
    !isFragrantPairSeerPreset(config)
  )
    return "fragrant_pair_seer_preset_invalid";
  if (
    (config.nobleSecretBody ||
      config.nightNoble ||
      config.awakenedIdiot ||
      config.roleSetups.some(
        (row) => [Role.NightNoble, Role.AwakenedIdiot].includes(row.role) && row.count > 0,
      )) &&
    !isNobleSecretBodyPreset(config)
  )
    return "noble_secret_body_preset_invalid";
  if (
    (config.radiantEclipse ||
      config.roleSetups.some(
        (row) => (row.role === Role.RadiantCount || row.role === Role.EclipseMaid) && row.count > 0,
      )) &&
    !isRadiantEclipsePreset(config)
  )
    return "radiant_eclipse_preset_invalid";
  if (
    (config.mistRaven ||
      config.roleSetups.some(
        (row) => (row.role === Role.Alchemist || row.role === Role.RavenClawWolf) && row.count > 0,
      )) &&
    !isMistRavenPreset(config)
  )
    return "mist_raven_preset_invalid";
  if (
    (config.trickster ||
      config.roleSetups.some((row) => row.role === Role.Trickster && row.count > 0)) &&
    !isTricksterPreset(config)
  )
    return "trickster_preset_invalid";
  if (
    (config.scholarMentor ||
      config.roleSetups.some(
        (row) => (row.role === Role.DayScholar || row.role === Role.NightMentor) && row.count > 0,
      )) &&
    !isScholarMentorPreset(config)
  )
    return "scholar_mentor_preset_invalid";
  if (
    (config.timeConsort ||
      config.roleSetups.some((row) => row.role === Role.TimeWolfConsort && row.count > 0)) &&
    !isTimeConsortPreset(config)
  )
    return "time_consort_preset_invalid";
  if (
    (config.wolfSorcerer ||
      config.roleSetups.some((row) => row.role === Role.WolfSorcerer && row.count > 0)) &&
    !isWolfSorcererPreset(config)
  )
    return "wolf_sorcerer_preset_invalid";
  if (
    (config.magician ||
      config.roleSetups.some((row) => row.role === Role.Magician && row.count > 0)) &&
    !isMagicianPreset(config)
  )
    return "magician_preset_invalid";
  if (
    (config.redMoon ||
      config.roleSetups.some((row) => row.role === Role.RedMoonApostle && row.count > 0)) &&
    !isRedMoonPreset(config)
  )
    return "red_moon_preset_invalid";
  if (
    (config.nightmareShadow ||
      config.roleSetups.some((row) => row.role === Role.NightmareShadow && row.count > 0)) &&
    !isNightmarePreset(config)
  )
    return "nightmare_preset_invalid";
  if (
    (config.evilKnight ||
      config.roleSetups.some((row) => row.role === Role.EvilKnight && row.count > 0)) &&
    !isEvilKnightPreset(config)
  )
    return "evil_knight_preset_invalid";
  if (
    (config.pureWhite ||
      config.wolfWitch ||
      config.roleSetups.some(
        (row) => (row.role === Role.PureWhiteGirl || row.role === Role.WolfWitch) && row.count > 0,
      )) &&
    !isPureWhitePreset(config)
  )
    return "pure_white_preset_invalid";
  if (
    config.roleSetups.some((row) => row.role === Role.DemonHunter && row.count > 0) ||
    config.demonHunter
  )
    if (!isDemonHunterPreset(config)) return "demon_hunter_preset_invalid";
  const ownsGhost = config.roleSetups.some((row) => row.role === Role.GhostBride && row.count > 0);
  if (
    ownsGhost ||
    config.ghostBride ||
    config.winConditions?.includes(WinCondition.ThreeFactionsElimination) ||
    config.winCondition === WinCondition.ThreeFactionsElimination
  )
    if (!isGhostBridePreset(config)) return "ghost_bride_preset_invalid";
  if (
    (config.orderPrince ||
      config.roleSetups.some((row) => row.role === Role.OrderPrince && row.count > 0)) &&
    !isOrderPrincePreset(config)
  )
    return "order_prince_preset_invalid";
  return null;
}

/**
 * Public ruleset setup boundary consumed by configuration and game assembly.
 * Exports finite inert support predicates, their ordered rejection dispatcher
 * and the distinct Node Demon Hunter ingress. These verdicts never execute a
 * game or grant action authority. Archive verification owns separate checks.
 */
export * from "./support";
export { boardPresetViolation } from "./board-support";
export { isDemonHunterPreset as isDemonHunterNodePreset } from "./node-board-support";

/**
 * Composes the existing native night failure and source-qualification policies.
 * Inputs are deferred original World reads, stage kinds and live read-only
 * ability references; outputs are the original rejection or continuation.
 * Every feature lookup retains its original short circuit and repeated World
 * read. Binding never queries a board, actor, resource, clock or request.
 * This query port cannot consume stock, settle a receipt or publish a fact.
 */
import type { World } from "../core/domain/world";
import { Role } from "../core/domain/identity";
import type { NightAbilityReadView } from "../game/mechanisms/roles/abilities";
import { isRadiantEclipseBoard } from "../game/mechanisms/roles/radiant_eclipse/ports";
import { isScholarMentorBoard } from "../game/mechanisms/roles/scholar_mentor/ports";
import { isTimeConsortBoard } from "../game/mechanisms/roles/time_wolf_consort/ports";
import { isMagicianBoard } from "../game/mechanisms/roles/magician/ports";
import { isNightmareBoard } from "../game/mechanisms/roles/nightmare_shadow/ports";
import {
  isEvilKnightBoard,
  assertEvilKnightNativeActor,
} from "../game/mechanisms/roles/evil_knight/ports";
import { isFragrantPairBoard } from "../game/mechanisms/roles/fragrant_pair_seer/ports";
import { isNobleBodyBoard } from "../game/mechanisms/roles/noble_secret_body/ports";
import { isMistRavenBoard } from "../game/mechanisms/roles/mist_raven/ports";
import {
  isRedMoonBoard,
  demonHunterActorId,
  demonWitchRequiredThisNight,
} from "../game/mechanisms/roles/demon_hunter/ports";

export type NativeNightAction = "seer" | "guard" | "witch";

export interface NativeNightFailurePolicy {
  scopeStale(kind: NativeNightAction): void;
  actionMissing(kind: NativeNightAction): void;
  actionInvalid(kind: NativeNightAction): void;
  strictWolfFailurePrefix(): string | null;
  usesDemonController(): boolean;
  requiresDemonPotionTurn(): boolean;
  assertNativeActor(actorId: number, role: Role): void;
  assertSeerSource(ability: NightAbilityReadView<"seer_check">): void;
  assertPotionSource(ability: NightAbilityReadView<"potion">): void;
  skipsEmptyBorrowedPotion(ability: NightAbilityReadView<"potion">): boolean;
}

/** The delegate, rather than a cached World, preserves each original argument read. */
export function bindNativeNightFailurePolicy(world: () => World): NativeNightFailurePolicy {
  const scopeStale = (kind: NativeNightAction): void => {
    if (kind !== "guard" && isRadiantEclipseBoard(world()))
      throw new Error(`radiant_eclipse_${kind}_scope_stale`);
    if (isScholarMentorBoard(world())) throw new Error(`scholar_mentor_${kind}_scope_stale`);
    if (isTimeConsortBoard(world())) throw new Error(`time_consort_${kind}_scope_stale`);
  };
  const actionRejected = (kind: NativeNightAction, reason: "missing" | "invalid"): void => {
    if (kind !== "guard" && isRadiantEclipseBoard(world()))
      throw new Error(`radiant_eclipse_${kind}_action_${reason}`);
    if (isScholarMentorBoard(world())) throw new Error(`scholar_mentor_${kind}_action_${reason}`);
    if (isTimeConsortBoard(world())) throw new Error(`time_consort_${kind}_action_${reason}`);
    if (kind === "guard") {
      if (isEvilKnightBoard(world())) throw new Error(`evil_knight_guard_action_${reason}`);
      return;
    }
    if (isMagicianBoard(world())) throw new Error(`magician_${kind}_action_${reason}`);
    if (isEvilKnightBoard(world()) || isNightmareBoard(world()))
      throw new Error(
        isNightmareBoard(world())
          ? `nightmare_${kind}_action_${reason}`
          : `evil_knight_${kind}_action_${reason}`,
      );
  };
  return Object.freeze({
    scopeStale,
    actionMissing: (kind: NativeNightAction) => actionRejected(kind, "missing"),
    actionInvalid: (kind: NativeNightAction) => actionRejected(kind, "invalid"),
    strictWolfFailurePrefix() {
      if (isFragrantPairBoard(world())) return "fragrant_pair_seer";
      if (isNobleBodyBoard(world())) return "noble_secret_body";
      if (isRadiantEclipseBoard(world())) return "radiant_eclipse";
      if (isMistRavenBoard(world())) return "mist";
      if (isScholarMentorBoard(world())) return "scholar_mentor";
      if (isTimeConsortBoard(world())) return "time_consort";
      if (isNightmareBoard(world())) return "nightmare";
      if (isMagicianBoard(world())) return "magician";
      if (isRedMoonBoard(world())) return "red_moon";
      if (isEvilKnightBoard(world())) return "evil_knight";
      return null;
    },
    usesDemonController: () => demonHunterActorId(world()) !== null,
    requiresDemonPotionTurn: () => demonWitchRequiredThisNight(world()),
    assertNativeActor: (actorId: number, role: Role) =>
      assertEvilKnightNativeActor(world(), actorId, role),
    assertSeerSource(ability: NightAbilityReadView<"seer_check">) {
      if (
        isEvilKnightBoard(world()) &&
        (ability.source.kind !== "native" || ability.source.role !== Role.Seer)
      )
        throw new Error("evil_knight_seer_source_invalid");
    },
    assertPotionSource(ability: NightAbilityReadView<"potion">) {
      if (
        isEvilKnightBoard(world()) &&
        (ability.source.kind !== "native" || ability.source.role !== Role.Witch)
      )
        throw new Error("evil_knight_witch_source_invalid");
    },
    skipsEmptyBorrowedPotion: (ability: NightAbilityReadView<"potion">) =>
      isRadiantEclipseBoard(world()) &&
      ability.source.kind === "copy" &&
      ability.state.heal === 0 &&
      ability.state.poison === 0,
  });
}

/**
 * Composes native mapped/reflected targets and the existing potion request hints.
 * Inputs are deferred context/day/target reads; outputs preserve original target
 * references and readonly receipt views without exposing a receipt commit method.
 * Every board check and resolver argument is evaluated at its old position.
 * Binding never selects an actor, snapshots inventory, invokes a getter or spends
 * stock. Paid receipt consumption belongs to the separate native effect port.
 */
import type { NightStageContext } from "../game/mechanisms/stages/night/contracts";
import type { NightLifeScope } from "../core/domain/night_effects";
import type { AliveComponent } from "../core/domain/components/alive";
import {
  isMagicianBoard,
  resolveMagicianNightTarget,
  type MagicianResolvedTarget,
} from "../game/mechanisms/roles/magician/ports";
import {
  isTimeConsortBoard,
  resolveTimeConsortTarget,
  type TimeConsortReceipt,
} from "../game/mechanisms/roles/time_wolf_consort/ports";
import {
  isScholarMentorBoard,
  scholarMentorBlocks,
} from "../game/mechanisms/roles/scholar_mentor/ports";

export type NativeTargetScope = Readonly<Omit<NightLifeScope, "life">> & {
  readonly life: Readonly<AliveComponent>;
};
export type NativeMappedTarget = Omit<MagicianResolvedTarget, "scope"> & {
  readonly scope: NativeTargetScope;
};
export type NativeReflectedTarget = Omit<TimeConsortReceipt, "commit" | "scope"> & {
  readonly scope: NativeTargetScope;
};

export interface NativeNightTargetPolicy {
  mappedTarget(day: () => number, targetId: () => number): NativeMappedTarget | null;
  reflectedTarget(
    day: () => number,
    sourceId: () => number,
    targetId: () => number,
    kind: "check" | "guard" | "poison",
  ): NativeReflectedTarget | null;
  potionModifierHints(actorId: number): { modifier_poison_blocked?: boolean };
  potionKnifeHints(): { wolf_targets?: number[] };
}

type TargetRuntime = Pick<NightStageContext, "world" | "currentDay" | "state">;

/** Delegation remains lazy even when a caller's day or target is accessor-backed. */
export function bindNativeNightTargetPolicy(context: () => TargetRuntime): NativeNightTargetPolicy {
  return Object.freeze({
    mappedTarget(day: () => number, targetId: () => number) {
      return isMagicianBoard(context().world)
        ? resolveMagicianNightTarget(context().world, day(), targetId())
        : null;
    },
    reflectedTarget(
      day: () => number,
      sourceId: () => number,
      targetId: () => number,
      kind: "check" | "guard" | "poison",
    ) {
      return isTimeConsortBoard(context().world)
        ? resolveTimeConsortTarget(context().world, day(), sourceId(), targetId(), kind)
        : null;
    },
    potionModifierHints(actorId: number) {
      return isScholarMentorBoard(context().world)
        ? {
            modifier_poison_blocked: scholarMentorBlocks(
              context().world,
              context().currentDay(),
              actorId,
              "poison",
            ),
          }
        : {};
    },
    potionKnifeHints() {
      return isScholarMentorBoard(context().world)
        ? {
            wolf_targets: [
              ...new Set(
                [
                  context().state.wolfTarget,
                  ...(context().state.modifierKnifeTargets ?? []),
                ].filter((id): id is number => id !== null),
              ),
            ],
          }
        : {};
    },
  });
}

/**
 * Owns explicit compatibility and Ghost Bride replacement registration policies.
 * Inputs are already collected handler references and compiler-provided wedding
 * handlers; outputs are the registered Map, owned replacement refs or a named conflict.
 * Profile and compiler reservations share only the same original handler for an
 * observed ID. No duplicate priority/execute getters, actor queries or coercion
 * run here; declared replacements preserve their original four-step order. Clone
 * refs are captured at the original argument position and recorded after set succeeds.
 */
import type { NightStageHandler } from "../game/mechanisms/stages/night/contracts";
import type { GhostStageRegistrationChange } from "./night-stage-plan-contracts";

export const NIGHT_STAGE_SHARING = Object.freeze({
  compatibility: "same-original-handler-reference",
  sources: Object.freeze(["role-profile", "compiler-reservation"] as const),
  conflictCode: "night_stage_handler_conflict",
} as const);

/** These are finite existing operations, not a general replacement graph. */
export const GHOST_BRIDE_STAGE_OPERATIONS = Object.freeze([
  Object.freeze({ kind: "remove", id: "wolf_kill_vote" } as const),
  Object.freeze({ kind: "install", source: "wedding-chat" } as const),
  Object.freeze({ kind: "install", source: "wedding-knife" } as const),
  Object.freeze({ kind: "reprioritize-if-present", id: "wolf_discussion", priority: 350 } as const),
] as const);

export function registerNightStages(
  collected: readonly NightStageHandler[],
): Map<string, NightStageHandler> {
  const registered = new Map<string, NightStageHandler>();
  for (const stage of collected) {
    const observedId = stage.id;
    if (!registered.has(observedId)) {
      // Keep the original second ID evaluation for a newly registered winner.
      const registeredId = stage.id,
        existing = registered.get(registeredId);
      if (existing !== undefined && existing !== stage) conflict(registeredId);
      registered.set(registeredId, stage);
    } else if (registered.get(observedId) !== stage) {
      conflict(observedId);
    }
  }
  return registered;
}

function conflict(observedId: string): never {
  const suffix = typeof observedId === "string" ? `:${observedId}` : "";
  throw new Error(NIGHT_STAGE_SHARING.conflictCode + suffix);
}

export function applyGhostBrideStageRegistration(
  registered: Map<string, NightStageHandler>,
  weddingChat: NightStageHandler,
  weddingKnife: NightStageHandler,
): readonly GhostStageRegistrationChange[] {
  const changes: GhostStageRegistrationChange[] = [];
  for (const operation of GHOST_BRIDE_STAGE_OPERATIONS) {
    switch (operation.kind) {
      case "remove":
        registered.delete(operation.id);
        break;
      case "install": {
        const stage = operation.source === "wedding-chat" ? weddingChat : weddingKnife;
        registered.set(stage.id, stage);
        changes.push(Object.freeze({ handler: stage, operation: operation.source }));
        break;
      }
      case "reprioritize-if-present": {
        const chat = registered.get(operation.id);
        if (chat) {
          let replacement: NightStageHandler = chat;
          registered.set(chat.id, (replacement = { ...chat, priority: operation.priority }));
          changes.push(
            Object.freeze({
              handler: replacement,
              original: chat,
              operation: "ordinary-chat-priority",
            }),
          );
        }
        break;
      }
    }
  }
  return Object.freeze(changes);
}

/**
 * Responsibility: preserve Node ingress for the finite Demon Hunter board check.
 * Input: unknown candidate data; output: the original support boolean, returning
 * false for any snapshot or predicate failure. Domain snapshotPlainData rejects
 * Proxy before reflection and keeps depth 16, array limit 256 and the original
 * error code; the inert predicate then applies its own unchanged limits.
 * This setup check never installs state, grants a lease or pays a resource.
 */
import { snapshotPlainData } from "../core/domain/plain_data";
import { isDemonHunterPreset as readPreset } from "./support";

export function isDemonHunterPreset(input: unknown): boolean {
  try {
    return readPreset(
      snapshotPlainData(input, new Set<object>(), 0, 256, "demon_hunter_data_invalid"),
    );
  } catch {
    return false;
  }
}

/**
 * Owns the existing finite animal-dream composition predicate for production setup.
 * Inputs are inert normalized board data; outputs are the original support
 * verdict with unchanged field, deck, goal and policy checks. It never applies
 * game effects, chooses an actor or authorizes a turn. Archive verification has
 * a separately owned predicate and must not call this production implementation.
 */
import { copyEventData } from "@ai-werewolf-arena/game-contract";

import {
  ANIMAL_DREAM_POLICY,
  CAT_SKIPPED_VOTE_POLICIES,
  PUFFER_BALLOT_POLICIES,
} from "@ai-werewolf-arena/game-contract";

const deck: Readonly<Record<string, number>> = {
  wolf: 3,
  wolf_beauty: 1,
  villager: 4,
  white_cat: 1,
  fox_cub: 1,
  bear: 1,
  pufferfish: 1,
};
function record(v: unknown): v is Record<string, unknown> {
  return !!v && typeof v === "object" && !Array.isArray(v);
}
function exact(v: unknown, expected: Readonly<Record<string, unknown>>): boolean {
  return (
    record(v) &&
    Object.keys(v).length === Object.keys(expected).length &&
    Object.entries(expected).every(([k, item]) => Object.hasOwn(v, k) && v[k] === item)
  );
}
/** Four frozen candidate board shapes; runtime activation is separately checked by the role catalog. */
export function isAnimalDreamPreset(input: unknown): boolean {
  try {
    const c = copyEventData(input);
    if (!record(c)) return false;
    const required = [
      "boardSize",
      "enableSheriff",
      "animalDream",
      "whiteCat",
      "pufferfish",
      "bear",
      "wolfBeauty",
      "roleSetups",
      "hooks",
      "selfDestruct",
      "tieBreaker",
      "voting",
      "disclosure",
      "lastWords",
      "sheriff",
    ];
    if (
      !required.every((k) => Object.hasOwn(c, k)) ||
      Object.keys(c).some((k) => ![...required, "winConditions", "winCondition"].includes(k)) ||
      c.boardSize !== 12 ||
      c.enableSheriff !== true
    )
      return false;
    if (
      !exact(c.animalDream, {
        policy: ANIMAL_DREAM_POLICY,
        eliminationPriority: "awa_wolf_priority_v1",
      }) ||
      !exact(c.bear, { signalPolicy: "netease_dawn_live_v1" }) ||
      !exact(c.wolfBeauty, { deathLinkPolicy: "awa_exile_poison_v1" })
    )
      return false;
    if (
      !record(c.whiteCat) ||
      !CAT_SKIPPED_VOTE_POLICIES.includes(
        c.whiteCat.skippedVotePolicy as (typeof CAT_SKIPPED_VOTE_POLICIES)[number],
      ) ||
      !exact(c.whiteCat, { skippedVotePolicy: c.whiteCat.skippedVotePolicy })
    )
      return false;
    if (
      !record(c.pufferfish) ||
      !PUFFER_BALLOT_POLICIES.includes(
        c.pufferfish.ballotPolicy as (typeof PUFFER_BALLOT_POLICIES)[number],
      ) ||
      !exact(c.pufferfish, { ballotPolicy: c.pufferfish.ballotPolicy })
    )
      return false;
    if (!Array.isArray(c.roleSetups) || c.roleSetups.length !== Object.keys(deck).length)
      return false;
    const seen = new Set<string>();
    for (const row of c.roleSetups) {
      if (
        !record(row) ||
        typeof row.role !== "string" ||
        !Object.hasOwn(deck, row.role) ||
        seen.has(row.role) ||
        !exact(row, { role: row.role, count: deck[row.role] })
      )
        return false;
      seen.add(row.role);
    }
    if (Object.hasOwn(c, "winConditions") && !Array.isArray(c.winConditions)) return false;
    const goals = c.winConditions ?? (c.winCondition ? [c.winCondition] : []);
    if (
      !Array.isArray(goals) ||
      goals.length !== 1 ||
      goals[0] !== "slaughter_side" ||
      (Object.hasOwn(c, "winCondition") && c.winCondition !== goals[0])
    )
      return false;
    if (
      !exact(c.voting, { exilePolicy: "awa_one_pk_v1" }) ||
      !exact(c.disclosure, { deathRevealPolicy: "awa_hidden_v1" }) ||
      !exact(c.lastWords, { policy: "awa_initial_wave_v1" }) ||
      !exact(c.sheriff, {
        electionPolicy: "awa_nomination_offstage_pk_v1",
        badgePolicy: "awa_holder_choice_v1",
        voteWeight: 1.5,
      }) ||
      !exact(c.tieBreaker, {
        sheriffVote: "no_elimination",
        wolfKillVote: "min_id",
        exileVote: "no_elimination",
      }) ||
      !exact(c.hooks, {
        onDaybreak: false,
        onPreElection: true,
        onPreVote: true,
        onPerSpeechGap: false,
      })
    )
      return false;
    if (
      !record(c.selfDestruct) ||
      Object.keys(c.selfDestruct).length !== 1 ||
      !Array.isArray(c.selfDestruct.enabledWindows)
    )
      return false;
    const windows = c.selfDestruct.enabledWindows;
    return (
      windows.length === 2 &&
      new Set(windows).size === 2 &&
      windows.every((w: unknown) => w === "on_pre_election" || w === "on_pre_vote")
    );
  } catch {
    return false;
  }
}

/**
 * Owns the existing finite demon-hunter composition predicate for production setup.
 * Inputs are inert normalized board data; outputs are the original support
 * verdict with unchanged field, deck, goal and policy checks. It never applies
 * game effects, chooses an actor or authorizes a turn. Archive verification has
 * a separately owned predicate and must not call this production implementation.
 */
