        onDaybreak: false,
        onPreElection: true,
        onPreVote: true,
        onPerSpeechGap: false,
      })
    )
      return false;
    if (
      !record(c.selfDestruct) ||
      Object.keys(c.selfDestruct).length !== 1 ||
      !Array.isArray(c.selfDestruct.enabledWindows)
    )
      return false;
    const w = c.selfDestruct.enabledWindows;
    return (
      w.length === 2 &&
      new Set(w).size === 2 &&
      w.every((x) => x === "on_pre_election" || x === "on_pre_vote")
    );
  } catch {
    return false;
  }
}

/**
 * Owns the existing finite wolf-sorcerer composition predicate for production setup.
 * Inputs are inert normalized board data; outputs are the original support
 * verdict with unchanged field, deck, goal and policy checks. It never applies
 * game effects, chooses an actor or authorizes a turn. Archive verification has
 * a separately owned predicate and must not call this production implementation.
 */
import { copyEventData } from "@ai-werewolf-arena/game-contract";
const deck: Readonly<Record<string, number>> = {
  wolf: 3,
  wolf_sorcerer: 1,
  villager: 4,
  psychic: 1,
  witch: 1,
  hunter: 1,
  magician: 1,
};
function record(v: unknown): v is Record<string, unknown> {
  return !!v && typeof v === "object" && !Array.isArray(v);
}
function exact(v: unknown, expected: Record<string, unknown>): boolean {
  return (
    record(v) &&
    Object.keys(v).length === Object.keys(expected).length &&
    Object.entries(expected).every(([k, x]) => Object.hasOwn(v, k) && v[k] === x)
  );
}
/** Finite native twelve-player ordered Magician/Wolf Sorcerer combination. */
export function isWolfSorcererPreset(input: unknown): boolean {
  try {
    const c = copyEventData(input);
    if (!record(c)) return false;
    const required = [
      "boardSize",
      "enableSheriff",
      "magician",
      "wolfSorcerer",
      "hunter",
      "roleSetups",
      "hooks",
      "selfDestruct",
      "psychic",
      "witch",
      "tieBreaker",
      "voting",
      "disclosure",
      "lastWords",
      "sheriff",
    ];
    const allowed = [...required, "winCondition", "winConditions"];
    if (
      !required.every((k) => Object.hasOwn(c, k)) ||
      Object.keys(c).some((k) => !allowed.includes(k)) ||
      c.boardSize !== 12 ||
      c.enableSheriff !== true
    )
      return false;
    const m = c.magician;
    if (
      !record(m) ||
      (m.firstNight !== 1 && m.firstNight !== 2) ||
      (m.deathShotTargetPolicy !== "original" && m.deathShotTargetPolicy !== "exchanged") ||
      !exact(m, {
        policy: "awa_magician_wolf_king_v1",
        firstNight: m.firstNight,
        deathShotTargetPolicy: m.deathShotTargetPolicy,
      })
    )
      return false;
    if (!Array.isArray(c.roleSetups) || c.roleSetups.length !== Object.keys(deck).length)
      return false;
    const seen = new Set<string>();
    for (const row of c.roleSetups) {
      if (
        !record(row) ||
        typeof row.role !== "string" ||
        !Object.hasOwn(deck, row.role) ||
        seen.has(row.role) ||
        !exact(row, { role: row.role, count: deck[row.role] })
      )
        return false;
      seen.add(row.role);
    }
    if (Object.hasOwn(c, "winConditions") && !Array.isArray(c.winConditions)) return false;
    const goals = c.winConditions ?? (c.winCondition ? [c.winCondition] : []);
    if (
      !Array.isArray(goals) ||
      goals.length !== 1 ||
      goals[0] !== "slaughter_side" ||
      (Object.hasOwn(c, "winCondition") && c.winCondition !== goals[0])
    )
      return false;
    if (
      !exact(c.wolfSorcerer, { policy: "awa_wolf_sorcerer_seats_v1", firstNight: m.firstNight }) ||
      !exact(c.hunter, { deathActionPolicy: "awa_qualified_sources_v1" }) ||
      !exact(c.psychic, { inspectionPolicy: "awa_repeat_optional_v1" }) ||
      !exact(c.witch, {
        canSelfHeal: "disabled",
        knifeVisibility: "awa_with_heal_v1",
        potionPolicy: "awa_one_native_v1",
      }) ||
      !exact(c.voting, { exilePolicy: "awa_one_pk_v1" }) ||
      !exact(c.disclosure, { deathRevealPolicy: "awa_hidden_v1" }) ||
      !exact(c.lastWords, { policy: "awa_initial_wave_v1" }) ||
      !exact(c.sheriff, {
        electionPolicy: "awa_nomination_offstage_pk_v1",
        badgePolicy: "awa_holder_choice_v1",
        voteWeight: 1.5,
      }) ||
      !exact(c.tieBreaker, {
        sheriffVote: "no_elimination",
        wolfKillVote: "min_id",
        exileVote: "no_elimination",
      }) ||
      !exact(c.hooks, {
        onDaybreak: false,
        onPreElection: true,
        onPreVote: true,
        onPerSpeechGap: false,
      })
    )
      return false;
    if (
      !record(c.selfDestruct) ||
      Object.keys(c.selfDestruct).length !== 1 ||
      !Array.isArray(c.selfDestruct.enabledWindows)
    )
      return false;
    const w = c.selfDestruct.enabledWindows;
    return (
      w.length === 2 &&
      new Set(w).size === 2 &&
      w.every((x) => x === "on_pre_election" || x === "on_pre_vote")
    );
  } catch {
    return false;
  }
}

/**
 * 负责 bootstrap 的有限板子拒绝顺序与角色牌组构造。输入为原只读板子、可选固定底牌及窄 Catalog／事件支持查询；输出为原可写牌序或首个原拒绝。工厂及资料字段仍在原重复调用点读取，不复制或冻结来源。不创建 World／组件、消费 RNG、解析外部配置或授予权限；洗牌与装配时点仍由 bootstrap 维护。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, WinCondition } from "@ai-werewolf-arena/game-contract";
import { boardPresetViolation } from "./board-support";

/** Read-only metadata queries preserve the original catalog and profile identities. */
export interface SupportedRoleDeckCatalog {
  readonly requireMetadata: (role: Role) => {
    readonly maxCount?: number;
    readonly supportedWinConditions?: readonly WinCondition[];
    readonly supportedBoardRoles?: readonly Role[];
  };
  readonly getCamp: (role: Role) => Camp;
}

export function buildSupportedRoleDeck(
  config: ReadonlyBoardConfig,
  fixedRoles: readonly Role[] | undefined,
  getDefaultRoleCatalog: () => SupportedRoleDeckCatalog,
  supportsWallRoles: (roles: readonly Role[]) => boolean,
): Role[] {
  const presetViolation = boardPresetViolation(config);
  if (presetViolation) throw new Error(presetViolation);
  const deck: Role[] = [];
  for (const setup of config.roleSetups) {
    for (let i = 0; i < setup.count; i++) {
      deck.push(setup.role);
    }
  }

  if (
    config.events &&
    (!supportsWallRoles(deck) || config.events.pack !== "awa_wall_notes_once_v1")
  )
    throw new Error("event_pack_combination_not_supported");
  const counts = new Map<Role, number>();
  for (const role of deck) counts.set(role, (counts.get(role) ?? 0) + 1);
  for (const [role, count] of counts) {
    const maximum = getDefaultRoleCatalog().requireMetadata(role).maxCount;
    if (maximum !== undefined && count > maximum)
      throw new Error(`role_count_exceeds_limit: ${role}`);
  }
  for (const role of counts.keys()) {
    const profile = getDefaultRoleCatalog().requireMetadata(role);
    const conditions = config.winConditions?.length
      ? config.winConditions
      : [config.winCondition ?? WinCondition.SlaughterCity];
    if (
      profile.supportedWinConditions &&
      (new Set(conditions).size !== conditions.length ||
        conditions.some((condition) => !profile.supportedWinConditions!.includes(condition)))
    )
      throw new Error(`role_win_condition_not_supported: ${role}`);
    const supported = profile.supportedBoardRoles;
    if (supported && [...counts.keys()].some((candidate) => !supported.includes(candidate)))
      throw new Error(`role_combination_not_supported: ${role}`);
  }

  if (deck.length !== config.boardSize) {
    throw new Error(`Role setup mismatch: boardSize=${config.boardSize}, roles=${deck.length}`);
  }

  if (
    config.thief &&
    (!counts.has(Role.Thief) || config.thief.policy !== "lui_meme_thief_two_extra_villagers_v1")
  )
    throw new Error("thief_policy_invalid");
  if (
    config.lonelyGirl &&
    (!counts.has(Role.LonelyGirl) || config.lonelyGirl.policy !== "awa_netease_lonely_girl_v1")
  )
    throw new Error("lonely_girl_policy_invalid");
  if (
    counts.has(Role.LonelyGirl) &&
    (config.boardSize < 6 ||
      !counts.has(Role.Wolf) ||
      ![...counts.keys()].some(
        (role) => role !== Role.LonelyGirl && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
      ))
  )
    throw new Error("lonely_girl_finite_composition_required");
  if (
    config.wildChild &&
    (!counts.has(Role.WildChild) || config.wildChild.policy !== "awa_lui_meme_wild_child_v1")
  )
    throw new Error("wild_child_policy_invalid");
  if (
    counts.has(Role.WildChild) &&
    ((counts.get(Role.Wolf) ?? 0) < 1 ||
      [...counts]
        .filter(
          ([role]) =>
            role !== Role.WildChild && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
        )
        .reduce((n, [, count]) => n + count, 0) < 1)
  )
    throw new Error("wild_child_finite_composition_required");
  if (
    config.shapeshifter &&
    (!counts.has(Role.Shapeshifter) ||
      config.shapeshifter.policy !== "awa_netease_shapeshifter_two_extra_villagers_v1")
  )
    throw new Error("shapeshifter_policy_invalid");
  if (counts.has(Role.Shapeshifter)) {
    if (
      config.boardSize < 6 ||
      (counts.get(Role.Wolf) ?? 0) < 2 ||
      [...counts]
        .filter(
          ([role]) =>
            role !== Role.Shapeshifter && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
        )
        .reduce((n, [, count]) => n + count, 0) < 1
    )
      throw new Error("shapeshifter_finite_composition_required");
    deck.push(Role.Villager, Role.Villager);
  }
  if (counts.has(Role.Thief)) {
    if (
      (counts.get(Role.Wolf) ?? 0) < 2 ||
      [...counts]
        .filter(
          ([role]) => role !== Role.Thief && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
        )
        .reduce((n, [, count]) => n + count, 0) < 2
    )
      throw new Error("thief_finite_composition_required");
    deck.push(Role.Villager, Role.Villager);
  }
  if (fixedRoles) {
    if (
      fixedRoles.length !== deck.length ||
      [...fixedRoles].sort().join(",") !== [...deck].sort().join(",")
    )
      throw new Error("fixed_role_deck_mismatch");
    return [...fixedRoles];
  }
  return deck;
}

/**
 * Owns duplicate domain-tool schema compatibility and last-reference presentation selection.
 * Inputs are original ToolSpec references and the registry's owned Map; outputs are
 * the selected original references or a named schema conflict, without validating actions.
 * Different descriptions may override when complete own-data schemas have equal structure.
 * Node Proxy detection precedes reflection; accessors, inherited parameters and non-data
 * structures remain explicitly unverified legacy overrides and are never eagerly evaluated.
 * This policy does not freeze schemas, read World/clock/RNG or claim semantic JSON Schema
 * equivalence. Runtime parsing and its first-use cache remain ActionReception's responsibility.
 */
import { types } from "node:util";
import type { ToolName } from "@ai-werewolf-arena/game-contract";
import type { ToolSpec } from "../game/mechanisms/contracts";

export const TOOL_SCHEMA_CONFLICT = "tool_schema_conflict";

type SchemaStructure =
  | null
  | boolean
  | string
  | number
  | { kind: "object" | "array"; entries: [string, SchemaStructure][] };

type SchemaObservation = { kind: "data"; structure: SchemaStructure } | { kind: "opaque" };

const opaque: SchemaObservation = Object.freeze({ kind: "opaque" });

/** The bounded structural reader observes descriptors, never field getters or toJSON. */
function observeStructure(
  value: unknown,
  ancestors: Set<object>,
  budget: { remaining: number },
  depth: number,
): SchemaObservation {
  if (--budget.remaining < 0 || depth > 128) return opaque;
  if (
    value === null ||
    typeof value === "boolean" ||
    typeof value === "string" ||
    (typeof value === "number" && Number.isFinite(value))
  ) {
    return { kind: "data", structure: value };
  }
  if (typeof value !== "object" || types.isProxy(value) || ancestors.has(value)) return opaque;
  const array = Array.isArray(value),
    prototype = Object.getPrototypeOf(value);
  if (array ? prototype !== Array.prototype : prototype !== Object.prototype && prototype !== null)
    return opaque;
  const keys = Reflect.ownKeys(value);
  if (keys.some((key) => typeof key !== "string")) return opaque;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  const entries: [string, SchemaStructure][] = [];
  ancestors.add(value);
  try {
    for (const key of (keys as string[]).sort()) {
      const descriptor = descriptors[key];
      if (!descriptor || !("value" in descriptor)) return opaque;
      if (!descriptor.enumerable && !(array && key === "length")) return opaque;
      const child = observeStructure(descriptor.value, ancestors, budget, depth + 1);
      if (child.kind === "opaque") return opaque;
      entries.push([key, child.structure]);
    }
  } finally {
    ancestors.delete(value);
  }
  return { kind: "data", structure: { kind: array ? "array" : "object", entries } };
}

function observeParameters(spec: ToolSpec): SchemaObservation {
  if (types.isProxy(spec)) return opaque;
  const descriptor = Object.getOwnPropertyDescriptor(spec, "parameters");
  if (!descriptor || !("value" in descriptor)) return opaque;
  return observeStructure(descriptor.value, new Set(), { remaining: 65_536 }, 0);
}

function equalStructure(left: SchemaStructure, right: SchemaStructure): boolean {
  if (left === null || right === null || typeof left !== "object" || typeof right !== "object")
    return Object.is(left, right);
  return (
    left.kind === right.kind &&
    left.entries.length === right.entries.length &&
    left.entries.every(
      ([key, value], index) =>
        key === right.entries[index]![0] && equalStructure(value, right.entries[index]![1]),
    )
  );
}

function checkedName(registered: Map<ToolName, ToolSpec>, spec: ToolSpec): ToolName {
  const name = spec.name,
    previous = registered.get(name);
  if (previous !== undefined && previous !== spec) {
    const before = observeParameters(previous),
      after = observeParameters(spec);
    if (
      before.kind === "data" &&
      after.kind === "data" &&
      !equalStructure(before.structure, after.structure)
    ) {
      const suffix = typeof name === "string" ? `:${name}` : "";
      throw new Error(TOOL_SCHEMA_CONFLICT + suffix);
    }
  }
  return name;
}

/** Preserve Map.set lookup before the original single name read, then select the last ref. */
export function registerToolSpecs(
  registered: Map<ToolName, ToolSpec>,
  specs: readonly ToolSpec[],
): void {
  for (const spec of specs) {
    registered.set(checkedName(registered, spec), spec);
  }
}

