/**
 * 负责校验和规范化公开板子格式。输入为纯公开 JSON 与已登记角色声明；输出为原 BoardConfig、诊断和反向序列化配置。解析拥有字段／默认值规范化，规则集拥有有限支持裁决；不读取认证、执行对局或授予行动租约。
 */
import { boardPresetViolation } from "../../rulesets";
/** 唯一公开板子格式；未知字段和未注册角色保持原拒绝。 */
import { supportsWallRoles } from "../../game/mechanisms/events/wall_notes/authority";
import { z } from "zod";
import { RULESET } from "@ai-werewolf-arena/game-catalog";
import { ROLE_IDS, isRoleId } from "@ai-werewolf-arena/game-contract";
import { ActionWindow, Camp, Role, WinCondition, type BoardConfig } from "../../core/domain/model";
import { getDefaultRoleCatalog } from "../../game/mechanisms/roles/role-catalog-assembly";
import {
  EVENT_PACK_IDS,
  DEATH_REVEAL_POLICIES,
  LAST_WORDS_POLICIES,
  SHERIFF_BADGE_POLICIES,
  SHERIFF_ELECTION_POLICIES,
  EXILE_VOTE_POLICIES,
} from "../../core/domain/board";
import { boardConfigSchema } from "../../core/domain/board_schema";

export const CONFIG_ID_PATTERN = /^[a-z][a-z0-9_-]*$/;
export const MAX_BOARD_PLAYERS = 128;
export const boardIdSchema = z.string().regex(CONFIG_ID_PATTERN);
const safePositive = z.number().int().positive().max(Number.MAX_SAFE_INTEGER);
const hooks = z.strictObject({
  onDaybreak: z.boolean(),
  onPreElection: z.boolean(),
  onPreVote: z.boolean(),
  onPerSpeechGap: z.boolean(),
});
const schema = z.strictObject({
  version: z.literal(2),
  id: boardIdSchema,
  ruleset: z.strictObject({ id: z.literal(RULESET.id), version: z.literal(RULESET.version) }),
  board: z.strictObject({
    size: safePositive.max(MAX_BOARD_PLAYERS),
    roleSetups: z
      .array(
        z.strictObject({
          role: z.enum(ROLE_IDS as [string, ...string[]]),
          count: safePositive.max(MAX_BOARD_PLAYERS),
        }),
      )
      .min(1),
  }),
  rules: z.strictObject({ winConditions: z.array(z.enum(WinCondition)).min(1), hooks }),
  mechanisms: z.strictObject({
    eventPack: z.enum(EVENT_PACK_IDS).optional(),
    disclosure: z
      .strictObject({ deathRevealPolicy: z.enum(DEATH_REVEAL_POLICIES).default("awa_hidden_v1") })
      .default({ deathRevealPolicy: "awa_hidden_v1" }),
    lastWords: z
      .strictObject({ policy: z.enum(LAST_WORDS_POLICIES).default("awa_initial_wave_v1") })
      .default({ policy: "awa_initial_wave_v1" }),
    sheriff: z.strictObject({
      enabled: z.boolean(),
      electionPolicy: z.enum(SHERIFF_ELECTION_POLICIES).default("awa_final_candidates_v1"),
      badgePolicy: z.enum(SHERIFF_BADGE_POLICIES).default("awa_next_seat_v1"),
      initialSeat: safePositive.optional(),
      voteWeight: z.number().finite().positive().default(1.5),
      tieBreaker: z.enum(["min_id", "min_seat", "no_elimination"]).default("min_seat"),
    }),
    voting: z
      .strictObject({ exilePolicy: z.enum(EXILE_VOTE_POLICIES).default("awa_direct_v1") })
      .default({ exilePolicy: "awa_direct_v1" }),
    selfDestruct: z.strictObject({ enabledWindows: z.array(z.enum(ActionWindow)) }),
    tieBreaker: z.strictObject({
      exileVote: z.enum(["min_id", "no_elimination"]),
      wolfKillVote: z.enum(["min_id", "no_kill"]),
    }),
  }),
  roles: z.record(z.string(), z.unknown()).default({}),
});

export type BoardDefinition = z.infer<typeof schema>;
export interface ResolvedBoardDefinition {
  definition: BoardDefinition;
  config: BoardConfig;
  sourceFile?: string;
  fieldSources: Readonly<Record<string, "explicit" | "default">>;
}

export class BoardConfigurationError extends Error {
  constructor(
    readonly code: string,
    readonly fieldPath: string,
  ) {
    super(`${code}: ${fieldPath}`);
  }
}
function fail(code: string, path: string): never {
  throw new BoardConfigurationError(code, path);
}

export function parseBoardDefinition(raw: unknown, expectedId?: string): ResolvedBoardDefinition {
  const result = schema.safeParse(raw);
  if (!result.success) {
    const issue = result.error.issues[0];
    const key = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
    fail(
      "board_config_invalid_field",
      [...issue.path, ...(key ? [key] : [])].join(".") || "document",
    );
  }
  const definition = result.data;
  if (expectedId !== undefined && definition.id !== expectedId)
    fail("board_config_id_mismatch", "id");
  const catalog = getDefaultRoleCatalog();
  const seen = new Set<string>();
  let total = 0;
  for (const [index, entry] of definition.board.roleSetups.entries()) {
    if (!isRoleId(entry.role) || !catalog.metadata(entry.role as Role))
      fail("board_config_role_not_implemented", `board.roleSetups.${index}.role`);
    if (seen.has(entry.role)) fail("board_config_duplicate_role", `board.roleSetups.${index}.role`);
    const maximum = catalog.requireMetadata(entry.role as Role).maxCount;
    if (maximum !== undefined && entry.count > maximum)
      fail("board_config_invalid_field", `board.roleSetups.${index}.count`);
    seen.add(entry.role);
    total += entry.count;
  }
  if (total !== definition.board.size) fail("board_config_role_count_mismatch", "board.roleSetups");
  if (
    definition.board.roleSetups.some((row) => row.role === "shapeshifter") &&
    (definition.board.size < 6 ||
      definition.board.roleSetups
        .filter((row) => row.role === "wolf")
        .reduce((n, row) => n + row.count, 0) < 2 ||
      !definition.board.roleSetups.some(
        (row) => row.role !== "shapeshifter" && catalog.getCamp(row.role as Role) === Camp.Good,
      ))
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  if (definition.board.roleSetups.some((row) => row.role === "thief")) {
    const wolves = definition.board.roleSetups
        .filter((row) => row.role === "wolf")
        .reduce((n, row) => n + row.count, 0),
      good = definition.board.roleSetups
        .filter((row) => row.role !== "thief" && catalog.getCamp(row.role as Role) === Camp.Good)
        .reduce((n, row) => n + row.count, 0);
    if (wolves < 2 || good < 2)
      fail("board_config_role_combination_not_supported", "board.roleSetups");
  }
  if (
    definition.board.roleSetups.some((row) => row.role === "wild_child") &&
    !definition.board.roleSetups.some(
      (row) => row.role !== "wild_child" && catalog.getCamp(row.role as Role) === Camp.Good,
    )
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  if (
    definition.board.roleSetups.some((row) => row.role === "lonely_girl") &&
    (definition.board.size < 6 ||
      !definition.board.roleSetups.some((row) => row.role === "wolf") ||
      !definition.board.roleSetups.some(
        (row) => row.role !== "lonely_girl" && catalog.getCamp(row.role as Role) === Camp.Good,
      ))
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  const profiles = definition.board.roleSetups.map((entry) =>
    catalog.requireMetadata(entry.role as Role),
  );
  for (const profile of profiles) {
    if (
      profile.supportedBoardRoles &&
      definition.board.roleSetups.some(
        (entry) => !profile.supportedBoardRoles!.includes(entry.role as Role),
      )
    ) {
      fail("board_config_role_combination_not_supported", "board.roleSetups");
    }
  }
  if (
    !profiles.some((item) => item.camp === Camp.Wolf) ||
    !profiles.some((item) => item.camp === Camp.Good)
  ) {
    fail("board_config_requires_good_and_wolf", "board.roleSetups");
  }
  for (const profile of profiles)
    if (
      profile.supportedWinConditions &&
      definition.rules.winConditions.some(
        (condition) => !profile.supportedWinConditions!.includes(condition),
      )
    )
      fail("board_config_role_win_condition_not_supported", "rules.winConditions");
  if (new Set(definition.rules.winConditions).size !== definition.rules.winConditions.length)
    fail("board_config_duplicate_win_condition", "rules.winConditions");
  if (
    definition.mechanisms.eventPack &&
    !supportsWallRoles(definition.board.roleSetups.map((e) => e.role as Role))
  )
    fail("board_config_role_combination_not_supported", "mechanisms.eventPack");
  const sheriff = definition.mechanisms.sheriff;
  if (sheriff.initialSeat && sheriff.initialSeat > total)
    fail("board_config_seat_out_of_range", "mechanisms.sheriff.initialSeat");
  if (
    !sheriff.enabled &&
    (sheriff.initialSeat ||
      sheriff.voteWeight !== 1.5 ||
      sheriff.tieBreaker !== "min_seat" ||
      sheriff.electionPolicy !== "awa_final_candidates_v1" ||
      sheriff.badgePolicy !== "awa_next_seat_v1")
  ) {
    fail("board_config_disabled_mechanism_parameters", "mechanisms.sheriff");
  }
  const windows = definition.mechanisms.selfDestruct.enabledWindows;
  if (new Set(windows).size !== windows.length)
    fail("board_config_duplicate_window", "mechanisms.selfDestruct.enabledWindows");
  const windowHooks = {
    [ActionWindow.OnPreVote]: "onPreVote",
    [ActionWindow.OnDaybreak]: "onDaybreak",
    [ActionWindow.OnPreElection]: "onPreElection",
    [ActionWindow.OnPerSpeechGap]: "onPerSpeechGap",
  } as const;
  for (const window of windows)
    if (!definition.rules.hooks[windowHooks[window]])
      fail("board_config_window_hook_disabled", `rules.hooks.${windowHooks[window]}`);
  if (definition.rules.winConditions.includes(WinCondition.SlaughterSide)) {
    if (
      !profiles.some((item) => item.goodSide === "god") ||
      !profiles.some((item) => item.goodSide === "villager")
    ) {
      fail("board_config_slaughter_side_requires_both_sides", "rules.winConditions");
    }
  }
  let config: BoardConfig = {
    boardSize: total,
    roleSetups: definition.board.roleSetups.map((entry) => ({
      role: entry.role as Role,
      count: entry.count,
    })),
    winConditions: [...definition.rules.winConditions],
    hooks: { ...definition.rules.hooks },
    enableSheriff: sheriff.enabled,
    ...(sheriff.initialSeat ? { initialSheriffSeat: sheriff.initialSeat } : {}),
    ...(sheriff.enabled
      ? {
          sheriff: {
            voteWeight: sheriff.voteWeight,
            electionPolicy: sheriff.electionPolicy,
            badgePolicy: sheriff.badgePolicy,
          },
        }
      : {}),
    selfDestruct: { enabledWindows: [...windows] },
    ...(definition.mechanisms.eventPack
      ? { events: { pack: definition.mechanisms.eventPack } }
      : {}),
    voting: { ...definition.mechanisms.voting },
    disclosure: { ...definition.mechanisms.disclosure },
    lastWords: { ...definition.mechanisms.lastWords },
    tieBreaker: {
      ...definition.mechanisms.tieBreaker,
      ...(sheriff.enabled ? { sheriffVote: sheriff.tieBreaker } : {}),
    },
  };
  for (const [id, value] of Object.entries(definition.roles)) {
    if (!seen.has(id)) fail("board_config_role_parameters_without_role", `roles.${id}`);
    const contribution = catalog.requireRuntime(id as Role).configuration;
    if (!contribution) fail("board_config_role_parameters_not_supported", `roles.${id}`);
    const parsed = contribution.schema.safeParse(value);
    if (!parsed.success) {
      const issue = parsed.error.issues[0];
      const unknown = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
      fail(
        "board_config_invalid_field",
        ["roles", id, ...issue.path, ...(unknown ? [unknown] : [])].join("."),
      );
    }
    definition.roles[id] = parsed.data;
    config = contribution.apply(config, parsed.data);
  }
  for (const id of seen) {
    const contribution = catalog.requireRuntime(id as Role).configuration;
    if (contribution && !(id in definition.roles)) {
      const defaults = contribution.schema.parse(contribution.defaults);
      definition.roles[id] = defaults;
      config = contribution.apply(config, defaults);
    }
  }
  const presetViolation = boardPresetViolation(config);
  if (presetViolation) fail(`board_config_${presetViolation}`, "board");
  const fieldSources: Record<string, "explicit" | "default"> = {};
  const recordSources = (value: unknown, original: unknown, prefix: string) => {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      for (const [key, entry] of Object.entries(value)) {
        const prior =
          original && typeof original === "object"
            ? (original as Record<string, unknown>)[key]
            : undefined;
        recordSources(entry, prior, prefix ? `${prefix}.${key}` : key);
      }
    } else fieldSources[prefix] = original === undefined ? "default" : "explicit";
  };
  recordSources(definition, raw, "");
  return { definition, config, fieldSources };
}

/** 公开板子只含实际角色的参数；Tape 仍保留完整内部板子。 */
export function boardDefinitionFromConfig(id: string, config: BoardConfig): BoardDefinition {
  const valid = boardConfigSchema.safeParse(config);
  if (!valid.success) {
    const issue = valid.error.issues[0];
    const key = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
    fail("board_config_invalid_field", ["config", ...issue.path, ...(key ? [key] : [])].join("."));
  }
  const catalog = getDefaultRoleCatalog();
  const roles: Record<string, unknown> = {};
  for (const entry of config.roleSetups.filter((entry) => entry.count > 0)) {
    const contribution = catalog.requireRuntime(entry.role).configuration;
    if (contribution) roles[entry.role] = contribution.serialize(config);
  }
  const conditions = config.winConditions?.length
    ? config.winConditions
    : [config.winCondition ?? WinCondition.SlaughterCity];
  return parseBoardDefinition({
    version: 2,
    id,
    ruleset: RULESET,
    board: {
      size: config.boardSize,
      roleSetups: config.roleSetups.filter((entry) => entry.count > 0),
    },
    rules: { winConditions: conditions, hooks: config.hooks },
    mechanisms: {
      ...(config.events ? { eventPack: config.events.pack } : {}),
      disclosure: { deathRevealPolicy: config.disclosure?.deathRevealPolicy ?? "awa_hidden_v1" },
      lastWords: { policy: config.lastWords?.policy ?? "awa_initial_wave_v1" },
      sheriff: {
        enabled: config.enableSheriff,
        ...(config.enableSheriff
          ? {
              ...(config.initialSheriffSeat !== undefined
                ? { initialSeat: config.initialSheriffSeat }
                : {}),
              voteWeight: config.sheriff?.voteWeight ?? 1.5,
              electionPolicy: config.sheriff?.electionPolicy ?? "awa_final_candidates_v1",
              badgePolicy: config.sheriff?.badgePolicy ?? "awa_next_seat_v1",
              tieBreaker: config.tieBreaker?.sheriffVote ?? "min_seat",
            }
          : {}),
      },
      voting: { exilePolicy: config.voting?.exilePolicy ?? "awa_direct_v1" },
      selfDestruct: {
        enabledWindows: (config.selfDestruct?.enabledWindows ?? [ActionWindow.OnPreVote]).filter(
          (window) =>
            ({
              [ActionWindow.OnPreVote]: config.hooks.onPreVote,
              [ActionWindow.OnDaybreak]: config.hooks.onDaybreak,
              [ActionWindow.OnPreElection]: config.hooks.onPreElection,
              [ActionWindow.OnPerSpeechGap]: config.hooks.onPerSpeechGap,
            })[window],
        ),
      },
      tieBreaker: {
        exileVote: config.tieBreaker?.exileVote ?? "min_id",
        wolfKillVote: config.tieBreaker?.wolfKillVote ?? "min_id",
      },
    },
    roles,
  }).definition;
}

/**
 * 负责通用、警长和角色运行贡献的领域工具索引，以及有序本地化提示和指令。输入为原规格与指令数组；输出为同一规格和展示文字，不授予行动权限。重复的自有数据 schema 必须完全一致；兼容或不透明覆盖保留最后原引用与原文。参数 getter 和 schema 解析仍延迟至 ActionReception 首次使用；不合并 SDK／MCP 三项传输工具或写入领域状态。
 */
import { text, type Locale } from "@ai-werewolf-arena/game-text";
import { registerToolSpecs } from "../../../rulesets/tool-spec-registration";
import { ToolName } from "../../../core/domain/model";
import { COMMON_TOOL_SPECS } from "../common/tool_specs";
import { StageDirectiveRule, ToolSpec } from "../contracts";
import { RoleCatalog } from "../roles/catalog";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import { SHERIFF_TOOL_SPECS } from "../sheriff/tool_specs";

function buildDefaultSpecs(roleProfileRegistry: RoleCatalog): ToolSpec[] {
  const specs: ToolSpec[] = [...COMMON_TOOL_SPECS, ...SHERIFF_TOOL_SPECS];
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.toolSpecs) {
      specs.push(...profile.toolSpecs);
    }
  }
  return specs;
}

function buildDefaultStageDirectives(roleProfileRegistry: RoleCatalog): StageDirectiveRule[] {
  const directives: StageDirectiveRule[] = [];
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.stageDirectives) {
      directives.push(...profile.stageDirectives);
    }
  }
  return directives;
}

/** 工具规格注册表。 */
export class ToolSpecRegistry {
  private readonly specByName = new Map<ToolName, ToolSpec>();
  private readonly stageDirectives: StageDirectiveRule[];

  constructor(
    specs?: ToolSpec[],
    stageDirectives?: StageDirectiveRule[],
    roleProfileRegistry: RoleCatalog = getDefaultRoleCatalog(),
  ) {
    const effectiveSpecs = specs ?? buildDefaultSpecs(roleProfileRegistry);
    const effectiveDirectives = stageDirectives ?? buildDefaultStageDirectives(roleProfileRegistry);
    registerToolSpecs(this.specByName, effectiveSpecs);
    this.stageDirectives = [...effectiveDirectives];
  }

  get(name: ToolName): ToolSpec | undefined {
    return this.specByName.get(name);
  }

  getArgHint(name: ToolName): string | null {
    return this.specByName.get(name)?.argHint ?? null;
  }

  getUserPromptHint(name: ToolName, locale: Locale = "zh-CN"): string | null {
    const spec = this.specByName.get(name);
    return (
      spec?.userPromptHint ??
      (spec?.userPromptHintKey ? text(locale, spec.userPromptHintKey) : null)
    );
  }

  getStageDirective(allowedTools: ToolName[], locale: Locale = "zh-CN"): string | null {
    const matched = this.stageDirectives.find((rule) => rule.match(allowedTools));
    if (!matched) return null;
    // 调用方可以复制内建规则后覆盖原文；只在原文仍等于内建字节时采用对应翻译。
    return matched.messageKey && matched.text === text("zh-CN", matched.messageKey)
      ? text(locale, matched.messageKey)
      : matched.text;
  }

  getApplicableUserPromptHints(allowedTools: ToolName[], locale: Locale = "zh-CN"): string[] {
    return allowedTools
      .map((name) => this.getUserPromptHint(name, locale))
      .filter((item): item is string => Boolean(item));
  }
}

let defaultRegistry: ToolSpecRegistry | null = null;

/** 获取默认工具规格注册表实例。 */
export function getDefaultToolSpecRegistry(): ToolSpecRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ToolSpecRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责两个旧内置板子的覆盖层解析与规范化。输入为旧平铺／结构化数据和板子标识，输出覆盖层或合并后的 BoardConfig。
 * 先按原分支校验，保 default 与板子层优先级；只显式复制已列数组／对象，不作为任意深克隆或版本化板子文件加载器。
 */
import { z } from "zod";
import {
  ActionWindow,
  BoardConfig,
  HookConfig,
  Role,
  WinCondition,
  WitchSelfHealRule,
} from "../../core/domain/model";
import { getDefaultConfigNormalizerRegistry } from "../../game/mechanisms";
import { sixPlayerMvpConfig } from "./six_player_mvp";
import { twelvePlayerStandardConfig } from "./twelve_player_standard";

/** 仅此旧兼容解析器的两个标识，不是全部可配置角色／版本化板子的支持目录。 */
export type BoardName = "six_player_mvp" | "twelve_player_standard";
type JsonObject = Record<string, unknown>;
export type BoardOverride = Omit<
  Partial<BoardConfig>,
  "hooks" | "sheriff" | "witch" | "tieBreaker" | "selfDestruct"
> & {
  hooks?: Partial<HookConfig>;
  sheriff?: NonNullable<BoardConfig["sheriff"]>;
  witch?: NonNullable<BoardConfig["witch"]>;
  tieBreaker?: NonNullable<BoardConfig["tieBreaker"]>;
  selfDestruct?: NonNullable<BoardConfig["selfDestruct"]>;
};

/** 旧结构化输入的分区数据；通过 schema 后映射到同一 BoardOverride，不授予执行许可。 */
type StructuredBoardConfig = {
  board?: {
    size?: number;
    roleSetups?: unknown;
  };
  rules?: {
    winCondition?: unknown;
    winConditions?: unknown;
    hooks?: Partial<HookConfig>;
  };
  mechanisms?: {
    sheriff?: {
      enabled?: boolean;
      initialSeat?: number;
      voteWeight?: number;
      tieBreaker?: unknown;
    };
    selfDestruct?: {
      enabledWindows?: unknown;
    };
    tieBreaker?: {
      exileVote?: unknown;
      wolfKillVote?: unknown;
    };
  };
  roles?: {
    witch?: {
      selfHeal?: unknown;
    };
  };
};

const tieBreaker = z.enum(["min_id", "min_seat", "no_elimination", "no_kill"]);
const hooks = z.strictObject({
  onDaybreak: z.boolean().optional(),
  onPreElection: z.boolean().optional(),
  onPreVote: z.boolean().optional(),
  onPerSpeechGap: z.boolean().optional(),
});
const flatOverride = z.strictObject({
  boardSize: z.number().int().positive().optional(),
  enableSheriff: z.boolean().optional(),
  initialSheriffSeat: z.number().int().positive().optional(),
  winCondition: z.enum(WinCondition).optional(),
  winConditions: z.array(z.enum(WinCondition)).optional(),
  hooks: hooks.optional(),
  selfDestruct: z.strictObject({ enabledWindows: z.array(z.enum(ActionWindow)) }).optional(),
  sheriff: z.strictObject({ voteWeight: z.number().positive().optional() }).optional(),
  witch: z.strictObject({ canSelfHeal: z.enum(WitchSelfHealRule).optional() }).optional(),
  tieBreaker: z
    .strictObject({
      exileVote: tieBreaker.optional(),
      wolfKillVote: tieBreaker.optional(),
      sheriffVote: tieBreaker.optional(),
    })
    .optional(),
  roleSetups: z
    .array(z.strictObject({ role: z.enum(Role), count: z.number().int().nonnegative() }))
    .optional(),
});
const structuredOverride = z.strictObject({
  board: z
    .strictObject({
      size: z.number().int().positive().optional(),
      roleSetups: flatOverride.shape.roleSetups,
    })
    .optional(),
  rules: z
    .strictObject({
      winCondition: flatOverride.shape.winCondition,
      winConditions: flatOverride.shape.winConditions,
      hooks: hooks.optional(),
    })
    .optional(),
  mechanisms: z
    .strictObject({
      sheriff: z
        .strictObject({
          enabled: z.boolean().optional(),
          initialSeat: z.number().int().positive().optional(),
          voteWeight: z.number().positive().optional(),
          tieBreaker: tieBreaker.optional(),
        })
        .optional(),
      selfDestruct: z
        .strictObject({ enabledWindows: z.array(z.enum(ActionWindow)).optional() })
        .optional(),
      tieBreaker: z
        .strictObject({ exileVote: tieBreaker.optional(), wolfKillVote: tieBreaker.optional() })
        .optional(),
    })
    .optional(),
  roles: z
    .strictObject({
      witch: z.strictObject({ selfHeal: z.enum(WitchSelfHealRule).optional() }).optional(),
    })
    .optional(),
});

function validateOverride(schema: z.ZodType, value: unknown): void {
  const result = schema.safeParse(value);
  if (!result.success) {
    const field = result.error.issues[0]?.path.join(".") || "document";
    throw new Error(`board_config_invalid_override_field: ${field}`);
  }
}

function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** 为旧基础板子复制下列可合并容器；未列字段仍按原 spread 引用保留，不承诺通用深克隆。 */
function cloneBoardConfig(config: BoardConfig): BoardConfig {
  return {
    ...config,
    roleSetups: config.roleSetups.map((item) => ({ ...item })),
    hooks: { ...config.hooks },
    ...(config.winConditions ? { winConditions: [...config.winConditions] } : {}),
    ...(config.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...config.selfDestruct.enabledWindows],
          },
        }
      : {}),
    ...(config.sheriff ? { sheriff: { ...config.sheriff } } : {}),
    ...(config.witch ? { witch: { ...config.witch } } : {}),
    ...(config.tieBreaker ? { tieBreaker: { ...config.tieBreaker } } : {}),
  };
}

/** 以 BoardConfig 语义合并覆盖项（保留数组/对象的显式拷贝）。 */
function mergeBoardConfig(base: BoardConfig, override: BoardOverride): BoardConfig {
  return {
    ...base,
    ...override,
    hooks: { ...base.hooks, ...(override.hooks ?? {}) },
    roleSetups: override.roleSetups
      ? override.roleSetups.map((item) => ({ ...item }))
      : base.roleSetups.map((item) => ({ ...item })),
    ...(override.winConditions ? { winConditions: [...override.winConditions] } : {}),
    ...(override.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...override.selfDestruct.enabledWindows],
          },
        }
      : base.selfDestruct
        ? {
            selfDestruct: {
              enabledWindows: [...base.selfDestruct.enabledWindows],
            },
          }
        : {}),
    sheriff: { ...(base.sheriff ?? {}), ...(override.sheriff ?? {}) },
    witch: { ...(base.witch ?? {}), ...(override.witch ?? {}) },
    tieBreaker: { ...(base.tieBreaker ?? {}), ...(override.tieBreaker ?? {}) },
  };
}

/** 以“覆盖层”语义合并 default + board 专属配置。 */
function mergeBoardOverride(base: BoardOverride, override: BoardOverride): BoardOverride {
  return {
    ...base,
    ...override,
    ...(base.hooks || override.hooks
      ? {
          hooks: {
            ...(base.hooks ?? {}),
            ...(override.hooks ?? {}),
          },
        }
      : {}),
    ...(base.sheriff || override.sheriff
      ? {
          sheriff: {
            ...(base.sheriff ?? {}),
            ...(override.sheriff ?? {}),
          },
        }
      : {}),
    ...(base.witch || override.witch
      ? {
          witch: {
            ...(base.witch ?? {}),
            ...(override.witch ?? {}),
          },
        }
      : {}),
    ...(base.tieBreaker || override.tieBreaker
      ? {
          tieBreaker: {
            ...(base.tieBreaker ?? {}),
            ...(override.tieBreaker ?? {}),
          },
        }
      : {}),
    ...(override.roleSetups
      ? {
          roleSetups: override.roleSetups.map((item) => ({ ...item })),
        }
      : base.roleSetups
        ? {
            roleSetups: base.roleSetups.map((item) => ({ ...item })),
          }
        : {}),
    ...(override.winConditions
      ? {
          winConditions: [...override.winConditions],
        }
      : base.winConditions
        ? {
            winConditions: [...base.winConditions],
          }
        : {}),
    ...(override.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...override.selfDestruct.enabledWindows],
          },
        }
      : base.selfDestruct
        ? {
            selfDestruct: {
              enabledWindows: [...base.selfDestruct.enabledWindows],
            },
          }
        : {}),
  };
}

/** 读取对应板子的内置默认配置。 */
function baseBoard(board: BoardName): BoardConfig {
  return board === "twelve_player_standard"
    ? cloneBoardConfig(twelvePlayerStandardConfig)
    : cloneBoardConfig(sixPlayerMvpConfig);
}

/** 判断对象是否为旧版平铺结构。 */
function isBoardOverrideShape(value: unknown): value is BoardOverride {
  if (!isJsonObject(value)) {
    return false;
  }
  const keys = Object.keys(value);
  const supported = new Set([
    "boardSize",
    "enableSheriff",
    "initialSheriffSeat",
    "winCondition",
    "winConditions",
    "hooks",
    "selfDestruct",
    "sheriff",
    "witch",
    "tieBreaker",
    "roleSetups",
  ]);
  return keys.some((key) => supported.has(key));
}

/** 判断对象是否为新版结构化配置。 */
function isStructuredBoardOverrideShape(value: unknown): value is StructuredBoardConfig {
  if (!isJsonObject(value)) {
    return false;
  }
  return ["board", "rules", "mechanisms", "roles"].some((key) => key in value);
}

/** 把新版 `board/rules/mechanisms/roles` 结构映射到 BoardConfig 覆盖层。 */
function parseStructuredBoardOverride(raw: StructuredBoardConfig): BoardOverride {
  const out: BoardOverride = {};

  if (isJsonObject(raw.board)) {
    if (typeof raw.board.size === "number") {
      out.boardSize = raw.board.size;
    }
    if (Array.isArray(raw.board.roleSetups)) {
      out.roleSetups = raw.board.roleSetups as BoardConfig["roleSetups"];
    }
  }

  if (isJsonObject(raw.rules)) {
    if (typeof raw.rules.winCondition === "string") {
      out.winCondition = raw.rules.winCondition as BoardConfig["winCondition"];
    }
    if (Array.isArray(raw.rules.winConditions)) {
      out.winConditions = raw.rules.winConditions as BoardConfig["winConditions"];
    }
    if (isJsonObject(raw.rules.hooks)) {
      out.hooks = {
        ...(typeof raw.rules.hooks.onDaybreak === "boolean"
          ? { onDaybreak: raw.rules.hooks.onDaybreak }
          : {}),
        ...(typeof raw.rules.hooks.onPreElection === "boolean"
          ? { onPreElection: raw.rules.hooks.onPreElection }
          : {}),
        ...(typeof raw.rules.hooks.onPreVote === "boolean"
          ? { onPreVote: raw.rules.hooks.onPreVote }
          : {}),
        ...(typeof raw.rules.hooks.onPerSpeechGap === "boolean"
          ? { onPerSpeechGap: raw.rules.hooks.onPerSpeechGap }
          : {}),
      } as HookConfig;
    }
  }

  if (isJsonObject(raw.mechanisms)) {
    if (isJsonObject(raw.mechanisms.sheriff)) {
      if (typeof raw.mechanisms.sheriff.enabled === "boolean") {
        out.enableSheriff = raw.mechanisms.sheriff.enabled;
      }
      if (typeof raw.mechanisms.sheriff.initialSeat === "number") {
        out.initialSheriffSeat = raw.mechanisms.sheriff.initialSeat;
      }
      if (typeof raw.mechanisms.sheriff.voteWeight === "number") {
        out.sheriff = {
          ...(out.sheriff ?? {}),
          voteWeight: raw.mechanisms.sheriff.voteWeight,
        };
      }
      if (typeof raw.mechanisms.sheriff.tieBreaker === "string") {
        // sheriff.tieBreaker 在新结构里归一到 tieBreaker.sheriffVote。
        out.tieBreaker = {
          ...(out.tieBreaker ?? {}),
          sheriffVote: raw.mechanisms.sheriff.tieBreaker as NonNullable<
            BoardConfig["tieBreaker"]
          >["sheriffVote"],
        };
      }
    }
    if (isJsonObject(raw.mechanisms.selfDestruct)) {
      if (Array.isArray(raw.mechanisms.selfDestruct.enabledWindows)) {
        out.selfDestruct = {
          enabledWindows: raw.mechanisms.selfDestruct.enabledWindows as NonNullable<
            BoardConfig["selfDestruct"]
          >["enabledWindows"],
        };
      }
    }
    if (isJsonObject(raw.mechanisms.tieBreaker)) {
      out.tieBreaker = {
        ...(out.tieBreaker ?? {}),
        ...(typeof raw.mechanisms.tieBreaker.exileVote === "string"
          ? {
              exileVote: raw.mechanisms.tieBreaker.exileVote as NonNullable<
                BoardConfig["tieBreaker"]
              >["exileVote"],
            }
          : {}),
        ...(typeof raw.mechanisms.tieBreaker.wolfKillVote === "string"
          ? {
              wolfKillVote: raw.mechanisms.tieBreaker.wolfKillVote as NonNullable<
                BoardConfig["tieBreaker"]
              >["wolfKillVote"],
            }
          : {}),
      };
    }
  }

  if (isJsonObject(raw.roles)) {
    if (isJsonObject(raw.roles.witch) && typeof raw.roles.witch.selfHeal === "string") {
      out.witch = {
        ...(out.witch ?? {}),
        canSelfHeal: raw.roles.witch.selfHeal as NonNullable<BoardConfig["witch"]>["canSelfHeal"],
      };
    }
  }

  return out;
}

/** 统一解析“单个配置块”成覆盖层（兼容新旧两种结构）。 */
function toBoardOverride(value: unknown): BoardOverride | null {
  // 先识别平铺再识别结构化；命中一种后按其严格字段集合验证，不在失败后换分支求通过。
  if (isBoardOverrideShape(value)) {
    validateOverride(flatOverride, value);
    return value as BoardOverride;
  }
  if (isStructuredBoardOverrideShape(value)) {
    validateOverride(structuredOverride, value);
    return parseStructuredBoardOverride(value);
  }
  return null;
}

/** 从 json 根对象提取目标板子的覆盖配置（含 boards/default 合并）。 */
export function parseBoardOverride(raw: unknown, board: BoardName): BoardOverride | null {
  const direct = toBoardOverride(raw);
  if (direct) {
    return direct;
  }
  if (!isJsonObject(raw)) {
    return null;
  }

  if ("boards" in raw || "default" in raw) {
    validateOverride(
      z.strictObject({
        boards: z
          .record(
            z.string().regex(/^[a-z][a-z0-9_-]*$/),
            z.union([flatOverride, structuredOverride]),
          )
          .optional(),
        default: z.union([flatOverride, structuredOverride]).optional(),
      }),
      raw,
    );
  } else {
    const allowed = new Set([board, "six_player_mvp", "twelve_player_standard"]);
    for (const [key, value] of Object.entries(raw)) {
      if (!allowed.has(key)) throw new Error("board_config_invalid_override_field: document");
      validateOverride(z.union([flatOverride, structuredOverride]), value);
    }
  }

  // boards 内目标优先，并仅在该分支叠加 default；根级同名板子的原分支不叠加 default。
  const boardsEntry = isJsonObject(raw.boards) ? raw.boards[board] : undefined;
  const boardOverride = toBoardOverride(boardsEntry);
  if (boardOverride) {
    const defaultOverride = toBoardOverride(raw.default);
    if (!defaultOverride) {
      return boardOverride;
    }
    return mergeBoardOverride(defaultOverride, boardOverride);
  }

  const keyedBoardOverride = toBoardOverride(raw[board]);
  if (keyedBoardOverride) {
    return keyedBoardOverride;
  }
  return null;
}

/** 合并并规范化板子配置；文件查找由加载层负责。 */
export function resolveBoardConfig(
  board: BoardName,
  override: BoardOverride | null = null,
): BoardConfig {
  const base = baseBoard(board);
  const merged = override ? mergeBoardConfig(base, override) : base;
  return getDefaultConfigNormalizerRegistry().normalize(merged);
}

/**
 * 负责独立审核赤月使徒延迟、转换与胜利前缀。输入为归档配置、决定、事实与 checkpoint；
 * 输出为独立重建的审计结果或原拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import { isRedMoonPreset } from "../../board-support";
import {
  readRedMoonNextNightFact,
  readRedMoonExpiryFact,
} from "@ai-werewolf-arena/game-contract/facts/red-moon";
import { Camp, Role, Phase, DeathCause } from "@ai-werewolf-arena/game-contract";
import type { ReproductionRecord } from "../../../recording/reproduction";
const roleId = "red_moon_apostle";
const factTypes = new Set([
  "red_moon_night_sealed",
  "red_moon_exile_delayed",
  "red_moon_delay_expired",
]);
interface State {
  policy: "awa_red_moon_demon_v1";
  lastWolfBlastPolicy: "ends_game" | "forbidden";
  blastDay: number | null;
  exileDay: number | null;
  expirySettled: boolean;
}
/** 事件位置的独立迁移证据供原生库存核验消费；readonly 类型不等于冻结 Set／Map。 */
export interface RedMoonRecordAudit {
  sealedNights: ReadonlySet<number>;
  expiredNights: ReadonlyMap<number, number>;
  stateAt(eventCount: number): State;
  idiotRevealedAt(eventCount: number): boolean;
}
function assert(value: unknown): asserts value {
  if (!value) throw new Error("reproduction_red_moon_state_invalid");
}
function equal(a: unknown, b: unknown): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}
/** 重建有限板子的公开状态迁移，不直接信任 checkpoint 中的库存。 */
export function validateRedMoonRecord(record: ReproductionRecord): RedMoonRecordAudit | null {
  const board = record.metadata.normalizedBoard;
  const owns = board.roleSetups.some((r) => String(r.role) === roleId && r.count > 0);
  const artifacts =
    record.events.some((e) => factTypes.has(e.type)) ||
    record.operations.some((o) => o.op === "red_moon_expiry_settled") ||
    record.checkpoints.some((cp) =>
      cp.players.some((p) => Object.hasOwn(p.privateState, "redMoon")),
    );
  if (!owns) {
    assert(!artifacts && !board.redMoon);
    return null;
  }
  assert(isRedMoonPreset(board) && !record.metadata.faultPlan && !record.metadata.initialDeal);
  const players = record.metadata.players,
    original = new Map(players.map((p) => [p.id, p]));
  const red = players.filter((p) => String(p.role) === roleId),
    idiots = players.filter((p) => p.role === Role.Idiot);
  assert(red.length === 1 && idiots.length === 1 && original.size === 12);
  const actorId = red[0]!.id,
    idiotId = idiots[0]!.id;
  const state: State = {
    policy: "awa_red_moon_demon_v1",
    lastWolfBlastPolicy: board.redMoon!.lastWolfBlastPolicy,
    blastDay: null,
    exileDay: null,
    expirySettled: false,
  };
  const states: State[] = [{ ...state }],
    idiotStates = [false];
  const alive = new Set(players.map((p) => p.id)),
    sealedNights = new Set<number>(),
    expiredNights = new Map<number, number>();
  const frozen = record.operations.filter((o) => o.op === "demon_hunter_sources_frozen");
  const expiryOps = record.operations.filter((o) => o.op === "red_moon_expiry_settled");
  let day = 1,
    phase: string = Phase.Night,
    voteTarget: number | null = null,
    idiotRevealed = false;
  let pendingSeal: number | null = null;
  const wolfCount = () => [...alive].filter((id) => original.get(id)?.camp === Camp.Wolf).length;
  const ordinaryAlive = (night: number) => {
    const op = frozen.find((o) => o.output?.day === night);
    assert(op && Array.isArray(op.output?.deaths));
    const ids = op.output.deaths as unknown[];
    assert(ids.every((id) => typeof id === "number" && original.has(id)));
    const remaining = new Set(alive);
    for (const id of ids) remaining.delete(id as number);
    return remaining;
  };
  const goodSidesRemain = (remaining: Set<number>) =>
    [...remaining].some((id) => original.get(id)?.role === Role.Villager) &&
    [...remaining].some(
      (id) => original.get(id)?.camp === Camp.Good && original.get(id)?.role !== Role.Villager,
    );
  for (let index = 0; index < record.events.length; index++) {
    const e = record.events[index]!;
    if (pendingSeal !== null) assert(e.type === "red_moon_night_sealed");
    if (e.type === "phase_changed") {
      assert(
        typeof e.payload.day === "number" &&
          Number.isSafeInteger(e.payload.day) &&
          e.payload.day > 0,
      );
      day = e.payload.day;
      phase = String(e.payload.phase);
      voteTarget = null;
    }
    if (e.type === "vote_summary") {
      assert(
        phase === Phase.Voting &&
          (e.payload.target === null || typeof e.payload.target === "number"),
      );
      voteTarget = e.payload.target as number | null;
    }
    if (e.type === "wolf_self_destruct") {
      const id = e.payload.wolfId;
      assert(typeof id === "number" && alive.has(id) && original.get(id)?.camp === Camp.Wolf);
      if (id === actorId) {
        assert(
          (phase === Phase.Day || phase === Phase.Voting) &&
            state.blastDay === null &&
            state.exileDay === null,
        );
        assert(wolfCount() > 1 || state.lastWolfBlastPolicy === "ends_game");
        pendingSeal = wolfCount() > 1 ? day : null;
        state.blastDay = day;
      }
      alive.delete(id);
    }
    if (e.type === "red_moon_night_sealed") {
      const fact = readRedMoonNextNightFact(e.type, e.payload);
      assert(
        fact &&
          fact.actorId === actorId &&
          fact.day === day &&
          pendingSeal === day &&
          record.events[index - 1]?.type === "wolf_self_destruct" &&
          record.events[index - 1]?.payload.wolfId === actorId &&
          !sealedNights.has(fact.night),
      );
      sealedNights.add(fact.night);
      pendingSeal = null;
    }
    if (e.type === "red_moon_exile_delayed") {
      const fact = readRedMoonNextNightFact(e.type, e.payload);
      assert(
        fact &&
          fact.actorId === actorId &&
          fact.day === day &&
          phase === Phase.Voting &&
          voteTarget === actorId &&
          alive.has(actorId) &&
          wolfCount() === 1 &&
          state.blastDay === null &&
          state.exileDay === null,
      );
      state.exileDay = day;
    }
    if (e.type === "idiot_revealed") {
      assert(
        e.payload.targetId === idiotId &&
          phase === Phase.Voting &&
          voteTarget === idiotId &&
          alive.has(idiotId) &&
          !idiotRevealed,
      );
      idiotRevealed = true;
    }
    if (e.type === "voted_out") {
      const id = e.payload.target;
      assert(
        typeof id === "number" && alive.has(id) && phase === Phase.Voting && voteTarget === id,
      );
      assert(id !== idiotId && !(id === actorId && wolfCount() === 1));
      alive.delete(id);
    }
    if (e.type === "red_moon_delay_expired") {
      const fact = readRedMoonExpiryFact(e.type, e.payload);
      assert(
        fact &&
          fact.actorId === actorId &&
          fact.day === day &&
          phase === Phase.Night &&
          state.exileDay === day - 1 &&
          !state.expirySettled &&
          alive.has(actorId) &&
          !expiredNights.has(day),
      );
      if (record.finalized) {
        const remaining = ordinaryAlive(day);
        assert(remaining.has(actorId) && goodSidesRemain(remaining));
        const ops = expiryOps.filter((o) => o.output?.day === day),
          source = frozen.find((o) => o.output?.day === day)!;
        assert(ops.length === 1);
        const op = ops[0]!;
        assert(
          op.scope === "resolution" &&
            op.phase === Phase.Night &&
            op.status === "ok" &&
            op.input === undefined &&
            equal(op.output, { actorId, day, cause: DeathCause.RedMoonExpiry }) &&
            record.operations.indexOf(source) < record.operations.indexOf(op),
        );
      }
      state.expirySettled = true;
      expiredNights.set(day, actorId);
    }
    if (e.type === "night_resolved") {
      assert(phase === Phase.Night && Array.isArray(e.payload.deaths));
      const deaths = e.payload.deaths as number[];
      assert(
        deaths.length === new Set(deaths).size &&
          deaths.every((id) => original.has(id) && alive.has(id)),
      );
      if (record.finalized) {
        const remaining = ordinaryAlive(day);
        const shouldExpire =
          state.exileDay === day - 1 && remaining.has(actorId) && goodSidesRemain(remaining);
        assert(expiredNights.has(day) === shouldExpire);
        if (shouldExpire) assert(deaths.includes(actorId));
      }
      for (const id of deaths) alive.delete(id);
    }
    if (factTypes.has(e.type)) assert(e.audience === undefined);
    states.push({ ...state });
    idiotStates.push(idiotRevealed);
  }
  if (record.finalized) {
    assert(expiryOps.length === expiredNights.size);
    if (record.checkpoints.at(-1)?.complete) assert(pendingSeal === null);
  }
  for (const d of record.decisions) {
    if (sealedNights.has(d.day)) assert(!["seer", "witch", "demon_hunter"].includes(d.stage));
    for (const e of d.request.context.visible_events) {
      if (!factTypes.has(e.type)) continue;
      assert(
        record.events.some((source) => source.type === e.type && equal(source.payload, e.payload)),
      );
    }
  }
  return {
    sealedNights,
    expiredNights,
    stateAt(count) {
      assert(Number.isSafeInteger(count) && count >= 0 && count < states.length);
      return { ...states[count]! };
    },
    idiotRevealedAt(count) {
      assert(Number.isSafeInteger(count) && count >= 0 && count < idiotStates.length);
      return idiotStates[count]!;
    },
  };
}
